<?php

/* Direct operations exercise ordering, conversion boundaries, sharing and failure without native slots. */
return [
	'write_normalized_keys' => ['$m mixed = {}; $d dynamic = {}; $m["10"] = 1; $m[10] = 2; $m["08"] = 3; $d["10"] = 4; $d[10] = 5; $a int = $m[10]; $b int = $m["08"]; $c int = $d[10];',
		'local_a.native_value() == 2 && local_b.native_value() == 3 && local_c.native_value() == 5 && (*local_m.shared_table_if())->size() == 2 && local_d->size() == 1'],
	'write_fail_nested_construction' => ['function store(mixed &$m): void { $m["new"] = {a: 1, a: 2}; }',
		'([&]() { scpp::mixed_t m{scpp::null}; bool caught = false; try { function_store(m); } catch (const std::exception&) { caught = true; } return caught && m.is_null().native_value(); }())'],
	'write_vector' => ['$v vector<int> = [1]; $v[0] = 2; $v[] = 3; $a = $v[0]; $b = $v[1];',
		'local_v.size() == 2 && local_a.native_value() == 2 && local_b.native_value() == 3'],
	'write_hash' => ['$h hash<int> = {}; $h["a"] = 1; $h["a"] = 2; $h["b"] = 3;',
		'local_h.size() == 2 && local_h.at(scpp::string_t{"a"}).native_value() == 2'],
	'write_integer_hash' => ['$h hash<int,int> = [8 => 1]; $h[] = 2; $h[3] = 3; $h[] = 4;',
		'local_h.size() == 4 && local_h.at(scpp::int_t<>{9LL}).native_value() == 2 && local_h.at(scpp::int_t<>{10LL}).native_value() == 4'],
	'write_mixed_copy' => ['$a mixed = {n: 1}; $b = $a; $a["n"] = 2; $a[] = 3; $x int = $b["n"];',
		'local_x.native_value() == 1 && (*local_a.shared_table_if())->size() == 2 && (*local_b.shared_table_if())->size() == 1'],
	'write_dynamic_share' => ['$a dynamic = {n: 1}; $b = $a; $a["n"] = 2; $a[] = 3; $x int = $b["n"];',
		'local_x.native_value() == 2 && local_b->size() == 2 && local_a.get() == local_b.get()'],
	'write_null_bootstrap' => ['$a mixed = null; $b mixed = null; $a["n"] = 5; $b[] = 7; $x int = $a["n"]; $y int = $b[0];',
		'local_x.native_value() == 5 && local_y.native_value() == 7'],
	'write_nested_literals' => ['$rows vector<vector<int>> = []; $rows[] = [1, 2]; $d dynamic = {}; $d["child"] = {n: 3}; $m mixed = {}; $m["child"] = {n: 4}; $x = $rows[0][1];',
		'local_x.native_value() == 2 && local_d->at(scpp::string_t{"child"}).dynamic_if() && (*local_m.shared_table_if())->at(scpp::string_t{"child"}).shared_table_if()'],
	'write_dynamic_box' => ['$child dynamic = {}; $d dynamic = {}; $m mixed = {}; $d["child"] = $child; $m[] = $child;',
		'local_d->at(scpp::string_t{"child"}).dynamic_if()->get() == local_child.get() && (*local_m.shared_table_if())->at(scpp::int_t<>{0LL}).dynamic_if()->get() == local_child.get()'],
	'write_checked_value' => ['$v vector<int> = []; $m mixed = 11; $v[] = $m; $k mixed = 0; $v[$k] = 13; $out = $v[0];',
		'local_out.native_value() == 13'],
	'write_order' => ['function key(int &$n): int { $n = $n * 10 + 1; return 0; } function value(int &$n): int { $n = $n * 10 + 2; return 17; } $n = 0; $v vector<int> = [0]; $v[key($n)] = value($n);',
		'local_n.native_value() == 12 && local_v.at(0).native_value() == 17'],
	'write_assignment_value' => ['$v vector<int> = []; $x = $v[] = 19; $y = ($v[0] = 23);',
		'local_x.native_value() == 19 && local_y.native_value() == 23 && local_v.at(0).native_value() == 23'],
	'write_parameter_modes' => ['function copy(vector<int> $v): void { $v[] = 2; } function mutate(vector<int> &$v): void { $v[] = 3; } $v vector<int> = [1]; copy($v); mutate($v);',
		'local_v.size() == 2 && local_v.at(1).native_value() == 3'],
	'write_fail_conversion' => ['function keyed(hash<int> &$h, mixed $v): void { $h["new"] = $v; } function appended(vector<int> &$v, mixed $x): void { $v[] = $x; }',
		'([&]() { scpp::hash_t<scpp::int_t<>> h; scpp::vector_t<scpp::int_t<>> v; scpp::mixed_t bad{true}; int caught = 0; try { function_keyed(h, bad); } catch (const std::exception&) { ++caught; } try { function_appended(v, bad); } catch (const std::exception&) { ++caught; } return caught == 2 && h.size() == 0 && v.size() == 0; }())'],
	'write_fail_key_order' => ['function store(mixed &$m, mixed $key, int &$n): void { $m[$key] = $n++; }',
		'([&]() { scpp::mixed_t m{scpp::null}; scpp::int_t<> n{0LL}; bool caught = false; try { function_store(m, scpp::mixed_t{true}, n); } catch (const std::exception&) { caught = true; } return caught && n.native_value() == 0 && m.is_null().native_value(); }())'],
	'write_fail_receivers' => ['function dynamicstore(dynamic &$d): void { $d["a"] = 1; } function dynamicappend(dynamic &$d): void { $d[] = 1; } function mixedstore(mixed &$m): void { $m["a"] = 1; } function vectorstore(vector<int> &$v): void { $v[0] = 1; }',
		'([&]() { scpp::dynamic_t<> d; scpp::mixed_t m{false}; scpp::vector_t<scpp::int_t<>> v; int caught = 0; try { function_dynamicstore(d); } catch (const std::exception&) { ++caught; } try { function_dynamicappend(d); } catch (const std::exception&) { ++caught; } try { function_mixedstore(m); } catch (const std::exception&) { ++caught; } try { function_vectorstore(v); } catch (const std::exception&) { ++caught; } return caught == 4 && !d.get() && !m.bool_value().native_value() && v.size() == 0; }())'],
];
